import React, { useEffect, useRef } from 'react';

const LiquidBackground = ({ darkMode = true }) => {
    const canvasRef = useRef(null);

    // Global specular cursor glow tracker for all Liquid Glass surfaces
    useEffect(() => {
        const handleMouseMove = (e) => {
            const panels = document.querySelectorAll('.saglix-glass, .clean-glass-card, .apple-pill');
            panels.forEach((panel) => {
                const rect = panel.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                panel.style.setProperty('--mouse-x', `${x}px`);
                panel.style.setProperty('--mouse-y', `${y}px`);
            });
        };

        window.addEventListener('mousemove', handleMouseMove, { passive: true });
        return () => window.removeEventListener('mousemove', handleMouseMove);
    }, []);

    // Zero-overlay 60fps Monochrome Abstract Liquid Gradient Canvas
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        let animationFrameId;
        let t = 0;

        const resize = () => {
            // Render at 0.5x scale for silky smooth liquid blur and low GPU load
            canvas.width = Math.max(320, Math.floor(window.innerWidth * 0.5));
            canvas.height = Math.max(240, Math.floor(window.innerHeight * 0.5));
        };

        resize();
        window.addEventListener('resize', resize);

        const render = () => {
            t += 0.008;
            const w = canvas.width;
            const h = canvas.height;

            // Base monochrome fill
            ctx.fillStyle = darkMode ? '#050507' : '#dce2ec';
            ctx.fillRect(0, 0, w, h);

            // Flowing abstract liquid ribbons
            const ribbons = darkMode
                ? [
                    { cx: 0.25 + Math.sin(t * 0.9) * 0.22, cy: 0.3 + Math.cos(t * 0.7) * 0.2, r: 0.55, c0: 'rgba(255,255,255,0.28)', c1: 'rgba(148,163,184,0.06)' },
                    { cx: 0.75 + Math.cos(t * 0.8) * 0.22, cy: 0.7 + Math.sin(t * 0.6) * 0.2, r: 0.6, c0: 'rgba(226,232,240,0.24)', c1: 'rgba(100,116,139,0.05)' },
                    { cx: 0.5 + Math.sin(t * 1.1 + 2) * 0.28, cy: 0.5 + Math.cos(t * 0.95 + 1) * 0.25, r: 0.48, c0: 'rgba(255,255,255,0.20)', c1: 'rgba(71,85,105,0.02)' },
                    { cx: 0.2 + Math.cos(t * 0.65 + 4) * 0.2, cy: 0.75 + Math.sin(t * 0.85 + 3) * 0.18, r: 0.45, c0: 'rgba(203,213,225,0.22)', c1: 'rgba(30,41,59,0.02)' },
                ]
                : [
                    { cx: 0.25 + Math.sin(t * 0.9) * 0.22, cy: 0.3 + Math.cos(t * 0.7) * 0.2, r: 0.55, c0: 'rgba(71,85,105,0.48)', c1: 'rgba(148,163,184,0.12)' },
                    { cx: 0.75 + Math.cos(t * 0.8) * 0.22, cy: 0.7 + Math.sin(t * 0.6) * 0.2, r: 0.6, c0: 'rgba(51,65,85,0.44)', c1: 'rgba(100,116,139,0.10)' },
                    { cx: 0.5 + Math.sin(t * 1.1 + 2) * 0.28, cy: 0.5 + Math.cos(t * 0.95 + 1) * 0.25, r: 0.48, c0: 'rgba(255,255,255,0.92)', c1: 'rgba(241,245,249,0.20)' },
                    { cx: 0.2 + Math.cos(t * 0.65 + 4) * 0.2, cy: 0.75 + Math.sin(t * 0.85 + 3) * 0.18, r: 0.45, c0: 'rgba(100,116,139,0.38)', c1: 'rgba(203,213,225,0.08)' },
                ];

            const maxDim = Math.max(w, h);
            ribbons.forEach((b) => {
                const x = b.cx * w;
                const y = b.cy * h;
                const radius = b.r * maxDim;
                const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                grad.addColorStop(0, b.c0);
                grad.addColorStop(0.55, b.c1);
                grad.addColorStop(1, 'rgba(0,0,0,0)');
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, w, h);
            });

            animationFrameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationFrameId);
            window.removeEventListener('resize', resize);
        };
    }, [darkMode]);

    return (
        <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden mono-liquid-stage">
            <canvas
                ref={canvasRef}
                className="w-full h-full object-cover scale-110 blur-2xl"
            />
        </div>
    );
};

export default LiquidBackground;
